// Full-column replace of every editable business field (deductions.go's
// UpdateDeduction precedent -- employee_pay_records keeps PATCH, unlike
// payroll_history/liquidation_history, per design R7's "employee_pay_records
// DOES keep PATCH -- loadPayRecords is an editable operator ledger").
// employee_id, company_id, origin, created_at stay immutable: the FK root,
// the tenant, and the write-path provenance are set at creation and never
// reassigned by edit. total_earned is RECOMPUTED here too (same rule as
// create -- it is a derived column regardless of which verb wrote it);
// net_salary is NOT recomputed, matching create.
func (q *Queries) UpdateEmployeePayRecord(ctx context.Context, arg UpdateEmployeePayRecordParams) (UpdateEmployeePayRecordRow, error) {
	row := q.db.QueryRow(ctx, updateEmployeePayRecord,
		arg.CompanyID,
		arg.ID,
		arg.EmployeeName,
		arg.Cedula,
		arg.NumeroPlanilla,
		arg.CentroCosto,
		arg.Periodo,
		arg.PeriodYear,
		arg.PeriodMonth,
		arg.GrossSalary,
		arg.OvertimeAmount,
		arg.Commissions,
		arg.Bonuses,
		arg.VacationsPaid,
		arg.OtherIncome,
		arg.CssEmployee,
		arg.SeEmployee,
		arg.Isr,
		arg.OtherDeductions,
		arg.NetSalary,
		arg.Notes,
	)
	var i UpdateEmployeePayRecordRow
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.EmployeeID,
		&i.EmployeeName,
		&i.Cedula,
		&i.NumeroPlanilla,
		&i.CentroCosto,
		&i.Periodo,
		&i.PeriodYear,
		&i.PeriodMonth,
		&i.GrossSalary,
		&i.OvertimeAmount,
		&i.Commissions,
		&i.Bonuses,
		&i.VacationsPaid,
		&i.OtherIncome,
		&i.TotalEarned,
		&i.CssEmployee,
		&i.SeEmployee,
		&i.Isr,
		&i.OtherDeductions,
		&i.NetSalary,
		&i.Notes,
		&i.Origin,
		&i.CreatedAt,
	)
	return i, err
}
